"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.21601",title:"Waypoint-OPD: Transferring RL-Induced Policy Shifts via Gated On-Policy Distillation",up:667,href:"https://arxiv.org/abs/2610.21601",abstract:"Policy-shift distillation reuses the difference between a teacher's log probabilities before and after reinforcement learning (RL) as supervision on student-generated trajectories. However, this endpoint policy shift cannot reveal whether local action preferences evolved consistently during teacher training. The same endpoint shift can result from early and late shifts that reinforce or partially cancel each other. We investigate whether agreement between early and late teacher policy shifts can guide selective transfer. We introduce Waypoint-guided On-Policy Distillation (Waypoint-OPD), which",pdfUrl:"https://arxiv.org/pdf/2610.21601",primaryCategory:"cs.LG",published:"2026-10-15T00:00:00Z"},{id:"2610.22276",title:"MJev-Spatial: System One Spatial Intelligence via Native Attention Matching",up:352,href:"https://arxiv.org/abs/2610.22276",abstract:"Spatial intelligence lets an agent perceive and act in the physical world, and many of its judgments must be made at interaction rates: which spatial relation holds, how far an object is, or where to place it. Vision-language models (VLMs) produce these answers by free-form text generation, paying for autoregressive decoding and answer parsing even though the output space is compact: one of a few options, a scalar, or a 2D point. In light of this, we introduce MJev-Spatial, a System 1 multimodal decision model that tackles all three types of spatial understanding tasks within a unified classif",pdfUrl:"https://arxiv.org/pdf/2610.22276",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.22200",title:"OpenGCUA: Toward a Fully Open Stack for Generalist Computer Use",up:316,href:"https://arxiv.org/abs/2610.22200",abstract:"Computer use has reached a turning point: the focus is expanding from GUI-only interaction to systems that complete tasks on users' computers through visual and programmatic interfaces. We define a generalist computer-use agent (GCUA) as a system in which the model chooses how to observe, act, and organize its work across visual and programmatic interfaces. Yet frontier implementations, such as GPT-6 Astra's computer-use system, remain largely closed, limiting systematic study of their design. We introduce Open Generalist CUA (OpenGCUA), an ongoing project to develop and open the full stack fo",pdfUrl:"https://arxiv.org/pdf/2610.22200",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.22350",title:"FDE-Gym: The Last Mile of AI Delivery",up:285,href:"https://arxiv.org/abs/2610.22350",abstract:"Existing agent benchmarks typically evaluate agents on well-specified tasks defined by issue reports, specifications, or task tickets. Real-world customer delivery is different: forward-deployed engineers (FDEs) must clarify ambiguous requirements, work in live systems, and uncover unstated constraints. We introduce FDE-Gym, a benchmark of 95 end-to-end delivery tasks from 20 customer scenarios across 18 sectors, each adapted by industry experts from real-world delivery projects. In simulated customer environments with scripted stakeholders and modifiable customer systems, agents interact with",pdfUrl:"https://arxiv.org/pdf/2610.22350",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.17665",title:"RoTA-Bench: Evaluating 3D Spatial Reasoning through Interactive Projection Alignment",up:201,href:"https://arxiv.org/abs/2610.17665",abstract:"Can vision-language models turn 2D observations into 3D understanding that supports precise action? This requires inferring object geometry, anticipating the effects of rotation, and refining actions through visual feedback. We introduce RoTA-Bench to evaluate these abilities through interactive 3D-to-2D projection alignment. Given a target silhouette, a model observes a rotated object and chooses successive rotations to recover the target projection within a limited action budget. Our automated pipeline constructs silhouette-preserving 3D objects from 2D icons and uses reversible initializati",pdfUrl:"https://arxiv.org/pdf/2610.17665",primaryCategory:"cs.AI",published:"2026-10-14T00:00:00Z"},{id:"2610.18813",title:"Self-Evolving Agent Harness",up:199,href:"https://arxiv.org/abs/2610.18813",abstract:"Harness self-evolution revises an agent's software scaffolding, including prompts, memory, workflows, and executable components, while keeping model weights fixed. We formalize a feedback-driven process in which accepted revisions persist across runs. The framework separates update targets from proposal and admission mechanisms. It distinguishes changes to interpreted state from revisions to tools and code, repository-level control logic, and plugin composition. We characterize search through evolutionary optimization and examine its reliability through continual PAC-learning. Under explicit a",pdfUrl:"https://arxiv.org/pdf/2610.18813",primaryCategory:"cs.AI",published:"2026-10-13T00:00:00Z"},{id:"2610.20939",title:"MAI-Gym: An Open All-in-One Platform for GUI Agent Evaluation and RL Training across Mobile and Computer Environments",up:154,href:"https://arxiv.org/abs/2610.20939",abstract:"Online reinforcement learning (RL) with verifiable rewards has driven rapid progress in mathematics, coding, and tool use, but scaling this success to GUI agents remains challenging due to the high cost of interactive environments and the scarcity of realistic training tasks. We introduce MAI-Gym, an open all-in-one platform that unifies GUI agent evaluation, data collection, and online RL training across mobile, computer, and web environments. Through a shared rollout pipeline, MAI-Gym ensures consistent agent behavior across evaluation and training, supports ten established benchmarks, and s",pdfUrl:"https://arxiv.org/pdf/2610.20939",primaryCategory:"cs.AI",published:"2026-10-14T00:00:00Z"},{id:"2610.21261",title:"Behavioral Compositionality of Sparse Autoencoder Representations",up:106,href:"https://arxiv.org/abs/2610.21261",abstract:"Sparse autoencoders (SAEs) represent model activations with sparse, linearly decoded features, but the downstream effects of those features need not compose additively. We introduce SAE Additivity Residuals (SAR), which measure the behavioral variation left unexplained above a chosen interaction order. Under independent feature subset sampling, population SAR is exactly the normalized energy of interactions above that order and bounds coalition ordering error for the optimal low order approximation. To distinguish compositionality associated with the SAE representation from that induced by dow",pdfUrl:"https://arxiv.org/pdf/2610.21261",primaryCategory:"cs.LG",published:"2026-10-15T00:00:00Z"},{id:"2610.21439",title:"Each Reward to Its Relevant Tokens: Reward-Specific Token-Level Credit Assignment for Multi-Reward RL",up:56,href:"https://arxiv.org/abs/2610.21439",abstract:"Language models are increasingly trained against several verifiable rewards at once, such as the correctness and the format of a tool call, or the individual constraints of a complex instruction. Reward-decoupled normalization (GDPO) normalizes each reward separately so that different reward combinations keep distinct advantages, but it still spreads every reward's advantage evenly over the whole response, although each verifier checks only a few positions. We propose MRTPO, which assigns the advantage of each reward to the tokens relevant to it, using the information its verifier checks, with",pdfUrl:"https://arxiv.org/pdf/2610.21439",primaryCategory:"cs.LG",published:"2026-10-15T07:47:04Z"},{id:"2610.21306",title:"VLA-Δ: Learning Physical State Transition for Vision-Language-Action Models",up:54,href:"https://arxiv.org/abs/2610.21306",abstract:"Vision-language-action (VLA) models transfer semantic knowledge acquired through vision-language pretraining to robot control, achieving strong performance across various benchmarks. However, most VLAs directly map observations to demonstrated actions without explicit supervision of intermediate physical state changes, making them prone to overfitting observation-action correspondences. Some methods introduce intermediate reasoning or future-state prediction in language, visual, or latent spaces to guide action generation, but do not explicitly supervise the physical state transition itself. W",pdfUrl:"https://arxiv.org/pdf/2610.21306",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.22174",title:"Mosaic: Multi-Session Agentic Reinforcement Learning",up:54,href:"https://arxiv.org/abs/2610.22174",abstract:"Most existing agentic reinforcement learning methods assume single-session trajectories, where interaction proceeds within one continuously accumulated context. However, agentic techniques such as context compaction and subagent forking may produce trajectories spanning multiple sessions, creating a mismatch between the single-session training assumption and inference-time execution. Therefore, we introduce Multi-Session Agentic Reinforcement Learning, a more general setting that supports an arbitrary number of sessions within a trajectory. Under this setting, a widely adopted method is to bro",pdfUrl:"https://arxiv.org/pdf/2610.22174",primaryCategory:"cs.CL",published:"2026-10-15T00:00:00Z"},{id:"2610.21095",title:"Can World and Action Modeling Benefit Each Other under Unified Causal Training?",up:40,href:"https://arxiv.org/abs/2610.21095",abstract:"World and action modeling are closely related, yet their reciprocal benefits under unified causal training remain unclear. We introduce OneWM, a simple framework for unified causal training that treats actions as both conditions for world prediction and targets for policy learning within a shared video-action architecture. Using this framework, we investigate whether learning forward dynamics conditioned on specified actions improves action learning, and whether learning to generate actions in turn improves action-conditioned world modeling. We use LIBERO, LIBERO-Plus, and RoboCasa365 as embod",pdfUrl:"https://arxiv.org/pdf/2610.21095",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.22355",title:"OmniVerifier-C1: Decomposed Graded Verifier for Rule-Governed Generative World Modeling",up:32,href:"https://arxiv.org/abs/2610.22355",abstract:"Generative visual verifiers play a crucial role in advancing multimodal intelligence. To enhance the robustness of visual verifiers in complex multimodal scenarios involving compositional requirements, we move beyond conventional binary verifiers that produce only True/False discrete judgments and introduce a verifier that automatically decomposes complex prompts or environmental rules into fine-grained components and assigns pointwise scores to provide a continuous and more informative critique signal. Our experiments further demonstrate that these structured and interpretable outputs improve",pdfUrl:"https://arxiv.org/pdf/2610.22355",primaryCategory:"cs.CL",published:"2026-10-15T00:00:00Z"},{id:"2610.20731",title:"WorldCast: Exploring Intelligent Visual Generation in World State Prediction",up:30,href:"https://arxiv.org/abs/2610.20731",abstract:"Humans interpret multimodal observations of the world and forecast how it will evolve. Recent multimodal generative systems have demonstrated similar capabilities: they can integrate multimodal context and synthesize visual outputs that depict changes in the world. To characterize this emerging trajectory, we organize model capabilities into a four-level hierarchy and discover that higher-level tasks remain relatively underexplored despite model progress. To bridge this gap, we explore model performance on multi-step world state prediction, a high-level task that requires models to forecast su",pdfUrl:"https://arxiv.org/pdf/2610.20731",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.21656",title:"Data World: Scaling Data Environments from Scratch",up:28,href:"https://arxiv.org/abs/2610.21656",abstract:"Data agents use code to process heterogeneous files and derive analytical insights. Scaling their training faces costly environment curation, privacy and intellectual-property restrictions, and difficulty verifying open-ended findings without known generative truth. Our core insight is to specify the world behind the files before generating the files themselves. We introduce Data World, a multi-agent engine that synthesizes environments, tasks, and rubrics from explicit mechanisms. Independent audits check target recoverability from observed files; rubrics support evaluation and RL rewards. Hu",pdfUrl:"https://arxiv.org/pdf/2610.21656",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.22344",title:"MLExpert: Towards a Generalist Agentic Model for Autonomous Machine Learning Engineering",up:25,href:"https://arxiv.org/abs/2610.22344",abstract:"Large language models (LLMs) are expanding from assisting scientific research and engineering to autonomously developing and improving AI systems, advancing AI for AI (AI4AI) as a pathway toward recursive self-improvement (RSI). Workflow-driven machine learning engineering (MLE) systems provide a practical path toward this pursuit through complex orchestration that manages long-horizon experimentation, while recent MLE systems adopt model-directed interaction, allowing models to autonomously organize experiments and adapt optimization strategies based on execution feedback. However, feedback f",pdfUrl:"https://arxiv.org/pdf/2610.22344",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.21463",title:"Trajectory-Level Speculation with Semantic Verification for Tool-Using Agents",up:21,href:"https://arxiv.org/abs/2610.21463",abstract:"Large language model agents solve tasks through long sequences of tool calls, and the prevailing design has a single strong model generate every step, although many steps are routine enough for a much smaller model. Existing ways of sharing this work keep the strong model as the generator: routers and collaborative agents decide which model handles each query or step, and speculative methods check a small model's drafts one step at a time, usually against the strong model's own action. We introduce SpecAgent, a collaboration protocol that turns the strong model from the author of each step int",pdfUrl:"https://arxiv.org/pdf/2610.21463",primaryCategory:"cs.CL",published:"2026-10-15T00:00:00Z"},{id:"2610.22322",title:"Learning Self-Orchestration in Decentralized Agent Swarms",up:11,href:"https://arxiv.org/abs/2610.22322",abstract:"The capabilities of an agent swarm depend on both its individual members and how they coordinate. Yet existing multi-agent systems often train agents within fixed orchestration structures, separating the learning of individual capabilities from the organization of collective behavior. We introduce market-based post-training (MPT), a framework for jointly learning action policies and self-orchestration in decentralized agent swarms. Agents express their willingness to participate through bids, which determine who acts and how collective outcomes provide local training credit. Learning both acti",pdfUrl:"https://arxiv.org/pdf/2610.22322",primaryCategory:"cs.MA",published:"2026-10-15T00:00:00Z"},{id:"2610.17959",title:"Virtual Head Attention",up:10,href:"https://arxiv.org/abs/2610.17959",abstract:"The design of attention mechanisms in long-context large language models faces an ``impossible triangle'' among KV cache size, training and prefill FLOPs, and model quality. GQA achieves strong quality but incurs high KV cache overhead; alternative approaches such as MLA and MFA can compress the cache, but MLA suffers from quality loss while MFA substantially increases training and prefill compute. We propose Virtual Head Attention (VHA), which simultaneously improves all three vertices through two lightweight linear operations: Q Premix applies a near-identity transformation to queries within",pdfUrl:"https://arxiv.org/pdf/2610.17959",primaryCategory:"cs.CL",published:"2026-10-13T00:00:00Z"},{id:"2610.21453",title:"CarryOn: A Dual-Loop Harness for Personalized and Reliable Robot Assistance",up:10,href:"https://arxiv.org/abs/2610.21453",abstract:'While generalist vision-language-action (VLA) models have enabled diverse open-world manipulation, real-world robotic assistance requires two critical capabilities they currently lack: personalization and reliable execution. First, executing an instruction like "make me a sandwich" requires grounding subtask decomposition in persistent user preferences rather than relying on a single generic solution. Second, reliable deployment demands explainable safety assurance that proactively prevents hazards and gracefully recovers from occasional physical failures. To address these gaps, we present Car',pdfUrl:"https://arxiv.org/pdf/2610.21453",primaryCategory:"cs.RO",published:"2026-10-15T00:00:00Z"},{id:"2610.22362",title:"CoDA: Co-Evolution of Data Engines and Action Policies",up:9,href:"https://arxiv.org/abs/2610.22362",abstract:"Generative simulation can automate robot environment construction, but physically valid environments are not necessarily useful for training. The challenge is to identify environments that address a policy's failures and supervision that helps it overcome them. We introduce CoDA, a framework in which a simulation data engine and an action policy co-evolve through a shared heterogeneous memory of environment construction, policy failures, and learning progress. The memory compiles validated diagnoses from a vision-language critic into generation programs that recreate difficulties and training ",pdfUrl:"https://arxiv.org/pdf/2610.22362",primaryCategory:"cs.RO",published:"2026-10-15T00:00:00Z"},{id:"2610.16105",title:"Beyond Policy Rollouts: Embedding-Space Directional Exploration with Anchored Noise for LLM RLVR",up:8,href:"https://arxiv.org/abs/2610.16105",abstract:"Reinforcement learning with verifiable rewards (RLVR) typically uses small rollout groups per prompt, where repeated sampling from the same policy can yield highly similar trajectories, reducing within-group reward variation and weakening group-relative advantage signals. Existing remedies such as higher sampling temperature, entropy bonuses, asymmetric clipping, and larger rollout budgets broaden sampling or modify policy updates but leave rollout conditioning unchanged. In this paper, we propose EDEN (Embedding-space Directional Exploration via anchored Noise), which intervenes at the rollou",pdfUrl:"https://arxiv.org/pdf/2610.16105",primaryCategory:"cs.LG",published:"2026-10-12T00:00:00Z"},{id:"2610.17901",title:"FlashMask-3: Efficient and Expressive Mask-Aware Distributed Attention",up:8,href:"https://arxiv.org/abs/2610.17901",abstract:"Long-context training of large language and multimodal models couples structured attention masks (document, prefix-LM, share-question, sliding-window, block-sparse) with multi-node context parallelism, making the mask a dominant bottleneck. FlashMask's column-wise sparse mask compresses them from $O(n^2)$ to $O(n)$ via four query-axis boundary vectors, covering broad structured patterns. Implemented for Ampere GPUs, it neither exploits FlashAttention-3's TMA/WGMMA warp-specialized pipeline on Hopper nor supports distribution. The column-wise sparse mask is indexed by key positions but stores q",pdfUrl:"https://arxiv.org/pdf/2610.17901",primaryCategory:"cs.LG",published:"2026-10-13T00:00:00Z"},{id:"2610.22352",title:"SUPRA-TEX: 3D Generation with Super-Aligned Texture",up:8,href:"https://arxiv.org/abs/2610.22352",abstract:"Single image 3D generation aims to dress a given 3D mesh with relightable materials while faithfully preserving the visual details of a reference image. Existing methods either introduce artifacts when fusing inconsistent multi-view predictions or struggle to preserve fine details through implicit image-feature conditioning. To resolve these challenges, we introduce SUPRA-Tex, built on the principle of decoupling visible-material estimation, surface alignment, and observation-guided 3D completion. This division of labor allows the 3D generator, trained on limited 3D data, to focus its capacity",pdfUrl:"https://arxiv.org/pdf/2610.22352",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"W7171516088",title:"SpecBox: Speculative Sandbox Scheduling for Efficient LLM Agent Serving",up:0,href:"https://doi.org/10.48550/arxiv.2607.23933",crossrefDoi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7171516088",crossrefIssued:"2026-08-24"},{id:"W7204032694",title:"Do Not Let Sandboxes Sit Idle: Cross-Agent Sandbox Re-allocation for LLM Agents",up:0,href:"https://doi.org/10.1007/978-981-92-4805-6_13",doi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7204032694"},{id:"W7221316450",title:"FHIR-AgentEval: a modular sandbox for benchmarking clinical LLM agents with memory-augmented configurations",up:0,href:"https://doi.org/10.1038/s41746-026-03348-0",doi:"https://doi.org/10.1038/s41746-026-03348-0",year:2026,openalexId:"https://openalex.org/W7221316450"}]}}]);